<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Validator};
use App\Services\WebsiteBackup;
class WebsiteBackupController extends Controller {
 public static function service(){return new WebsiteBackup(base_path(),dirname(base_path()).'/footstep-site-backups',DB::connection()->getPdo(),config('app.key'));}
 private function admin(){abort_unless(auth()->check()&&auth()->user()->user_type==='admin'&&!auth()->user()->banned,403);}
 private function validated($r,$rules){$v=Validator::make($r->all(),$rules+['password'=>'required|string|max:200','archive_password'=>'nullable|string|min:5|max:200'],['archive_password.required'=>'Backup ZIP-এর PIN/password দিন অথবা খালি রাখুন।','archive_password.min'=>'PIN/password দিলে অন্তত ৫ অক্ষর/সংখ্যা দিন; password না চাইলে খালি রাখুন।','password.required'=>'Current admin password দিন।']);if($v->fails())throw new \Illuminate\Http\Exceptions\HttpResponseException(response()->json(['message'=>'Check the required fields.','errors'=>$v->errors()->toArray()],422)->header('Cache-Control','no-store'));if(!Hash::check((string)$r->password,auth()->user()->password))throw new \Illuminate\Http\Exceptions\HttpResponseException(response()->json(['message'=>'Current admin password is incorrect.'],422)->header('Cache-Control','no-store'));$data=$v->validated();$data['archive_password']=(string)($data['archive_password']??'');return $data;}
 public function index(){$this->admin();try{$rows=self::service()->listing();}catch(\Throwable $e){\App\Services\BackupDiagnostics::record('backup_index_initialization_failed',500,bin2hex(random_bytes(8)),'website-backup.index',$e);$rows=[];}return response()->view('backend.platform.website_backups',['rows'=>$rows,'uploadLimit'=>ini_get('upload_max_filesize'),'postLimit'=>ini_get('post_max_size')])->header('Cache-Control','private, no-store');}
 public function create(Request $r){$this->admin();$d=$this->validated($r,[]);$id=self::service()->create($d['archive_password'],auth()->id());return response()->json(['id'=>$id,'message'=>'Full backup queued. Archive password is optional; keep it separately if set. Start/configure the background worker.'])->header('Cache-Control','no-store');}
 public function upload(Request $r){$this->admin();$d=$this->validated($r,['archive'=>'required|file|max:10485760']);$id=self::service()->import($r->file('archive')->getRealPath(),$d['archive_password'],auth()->id());return response()->json(['id'=>$id,'message'=>'Uploaded backup queued for checksum validation and password verification if protected.'])->header('Cache-Control','no-store');}
 public function action(Request $r,$id){$this->admin();$d=$this->validated($r,['action'=>'required|in:check,restore','scope'=>'required_if:action,restore|nullable|in:data,files,database,both','confirm'=>'required_if:action,restore|nullable|in:RESTORE']);$s=self::service();$job=$d['action']==='check'?$s->requestCheck($id,$d['archive_password'],auth()->id()):$s->requestRestore($id,$d['archive_password'],auth()->id(),$d['scope']);return response()->json(['id'=>$job,'message'=>$d['action']==='check'?'File/database checkup queued.':'Restore queued. Safety backup is mandatory before any restore write.'])->header('Cache-Control','no-store');}
 public function stop(Request $r,$id){$this->admin();try{$status=self::service()->requestStop($id,auth()->id());return response()->json(['id'=>$id,'status'=>$status,'message'=>'Stop requested. The worker will stop safely; the incomplete ZIP will not be downloadable.'])->header('Cache-Control','no-store');}catch(\RuntimeException $e){return response()->json(['message'=>$e->getMessage()],409)->header('Cache-Control','no-store');}}
 public function status($id){$this->admin();return response()->json(self::service()->status($id))->header('Cache-Control','private, no-store');}
 public function diagnostics(){$this->admin();return response()->json(['readiness'=>\App\Services\BackupDiagnostics::readiness(),'events'=>\App\Services\BackupDiagnostics::recent()])->header('Cache-Control','private, no-store');}
 public function download($id){$this->admin();$s=self::service();$j=$s->status($id);abort_unless($j['state']==='complete'&&in_array($j['kind'],['backup','inspect'],true),409);return response()->download($s->archivePath($id),'Footstep-Website-Backup-'.$id.'.zip',['Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
}
